-- ============================================================================
-- seed_etl_run_config_WIC.sql  (WIC step-driver package)
--
-- Seeds COMMON.ETL_RUN_CONFIG_TBL for workflow wf_WIC_Stage_Load: one row
-- per driver row (STEP_NO = 0, IS_DRIVER = 'Y') + every transform step +
-- every publish branch.  All IS_RUN_ENABLED = 'Y' (everything runs).
-- The DELETE below removes WIC rows only, so re-running this seed is safe.
-- Run it in the COMMON schema (MDM_ETL_COMMON.COMMON).
-- NOTE: IS_DEPENDENT / DEPENDENT_ON / WORK_TABLES_PRODUCED are informational
-- for a driver run — gating is by IS_RUN_ENABLED only.
-- ============================================================================

DELETE FROM ETL_RUN_CONFIG_TBL WHERE WORKFLOW_NAME = 'wf_WIC_Stage_Load';


-- 41 rows: 5 driver rows + 17 steps + 19 publish branches.
